{
  "resourceType": "ValueSet",
  "id": "diabetes-mellitus-cds",
  "url": "https://example.org/ValueSet/diabetes-mellitus-cds",
  "version": "20250301",
  "name": "DiabetesMellitusCDS",
  "title": "Diabetes mellitus - CDS rule value set",
  "status": "active",
  "description": "All types of diabetes mellitus for use in CDS rules. Intensional definition using ECL subsumption.",
  "compose": {
    "include": [
      {
        "system": "http://snomed.info/sct",
        "filter": [
          {
            "property": "constraint",
            "op": "=",
            "value": "<<73211009 |Diabetes mellitus (disorder)|"
          }
        ]
      }
    ]
  }
}

{
  "rule": "diabetes-nsaid-renal-alert",
  "when": {
    "all": [
      {
        "fact": "patient.age",
        "op": ">=",
        "value": 18
      },
      {
        "fact": "condition.code",
        "op": "inValueSet",
        "value": "https://example.org/ValueSet/diabetes-mellitus-cds"
      },
      {
        "fact": "medication.code",
        "op": "inECL",
        "value": "< 763158003 |Medicinal product| : 127489000 |Has active ingredient| = << 372665008 |Non-steroidal anti-inflammatory agent|"
      },
      {
        "fact": "observation[egfr].value",
        "op": "<",
        "value": 60
      }
    ]
  },
  "then": {
    "action": "alert",
    "message": "Review NSAID use - diabetes with reduced eGFR"
  }
}

# Check whether a patient's concept is within the CDS rule's value set
GET /fhir/ValueSet/$validate-code
  ?url=https://example.org/ValueSet/diabetes-mellitus-cds
  &system=http://snomed.info/sct
  &code=44054006

# Response: result=true means the patient concept is within the rule's value set
{
  "resourceType": "Parameters",
  "parameter": [
    { "name": "result", "valueBoolean": true },
    { "name": "display", "valueString": "Type 2 diabetes mellitus" }
  ]
}

# HISTORY-MIN: high precision - SAME AS associations only
# e.g. clinical decision support
<< 195967001 |Asthma (disorder)| {{ + HISTORY-MIN }}

# HISTORY-MOD: balances precision and recall
# SAME AS, REPLACED BY, WAS A, PARTIALLY EQUIVALENT TO
# e.g. clinical research, clinical audit
<< 195967001 |Asthma (disorder)| {{ + HISTORY-MOD }}

# HISTORY-MAX: highest recall - all historical associations
# e.g. identifying patients for manual review
<< 195967001 |Asthma (disorder)| {{ + HISTORY-MAX }}

