# Translate a SNOMED CT concept to ICD-10 using the official extended map
GET /fhir/ConceptMap/$translate
  ?url=http://snomed.info/sct/900000000000207008?fhir_cm=447562003
  &system=http://snomed.info/sct
  &code=73211009
  &targetsystem=http://hl7.org/fhir/sid/icd-10

# Response
{
  "resourceType": "Parameters",
  "parameter": [
    {
      "name": "result",
      "valueBoolean": true
    },
    {
      "name": "match",
      "part": [
        { "name": "equivalence", "valueCode": "equivalent" },
        {
          "name": "concept",
          "valueCoding": {
            "system": "http://hl7.org/fhir/sid/icd-10",
            "code": "E11",
            "display": "Type 2 diabetes mellitus"
          }
        }
      ]
    }
  ]
}

